import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"SelectionSummary","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/selection-summary.md","filePath":"workbench/selection-summary.md"}'),n={name:"workbench/selection-summary.md"};function r(s,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="selectionsummary" tabindex="-1">SelectionSummary <a class="header-anchor" href="#selectionsummary" aria-label="Permalink to &quot;SelectionSummary&quot;">​</a></h1><p>SelectionSummary is the panel of a selection of several things: how many of each kind, the fields they share and the actions on all of them.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it in place of the panel of a single thing, an <a href="./inspector-frame">InspectorFrame</a>, when several are selected. The application counts the things of each kind and names the kinds; it passes the editors of what the things share in <code>fields</code> and the actions on the whole selection in <code>actions</code>. An action that removes the selection goes in <code>end</code>, as an icon button, not among the actions.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>count</code></td><td>required</td><td>The number of things selected</td></tr><tr><td><code>kinds</code></td><td><code>[]</code></td><td>The number of each kind, <code>{ label, count }[]</code></td></tr><tr><td><code>title</code></td><td><code>selected</code> message</td><td>The title in the head</td></tr><tr><td><code>fields</code></td><td></td><td>The editors of what the things share (a snippet)</td></tr><tr><td><code>actions</code></td><td></td><td>The actions on the whole selection (a snippet)</td></tr><tr><td><code>end</code></td><td></td><td>Icon buttons in the head, before the close button (a snippet)</td></tr><tr><td><code>foot</code></td><td></td><td>The foot of the panel, a Footer with the actions (a snippet)</td></tr><tr><td><code>onclose</code></td><td></td><td>Shows a close button in the head</td></tr><tr><td><code>side</code></td><td><code>panel</code></td><td>The width, as <a href="./../components/panel">Panel</a>&#39;s <code>side</code></td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./../components/panel">Panel</a> with a <a href="./../components/toolbar">Toolbar</a> as its head, titled with the count (<code>3 selected</code> by default). The content is stacked with gap 0: the kinds as <a href="./../components/stats">Stats</a> in a <a href="./../components/block">Block</a>, then <code>fields</code> as they are (put them in <a href="./../components/section-header">SectionHeader</a> groups, which bring their padding), then <code>actions</code> in a Block. Without kinds, fields or actions, that part is left out.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/selection-summary/" title="SelectionSummary" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/selection-summary/" target="_blank" rel="noopener">SelectionSummary</a></figcaption></figure>',10)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
